// Pub/Sub push (with an OIDC push auth token configured on the subscription)
// delivers the token as a Bearer token in the Authorization header.
const headers = $json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const idToken = authHeader.replace(/^Bearer\s+/i, '').trim();

return {
  json: {
    id_token: idToken,
  },
};

// Input: the history.list response (or an error-shaped payload if that call failed).
// Output: one item carrying the account id, the deduped list of newly-added message
// ids, and the new cursor value to write regardless of message count (FR3, edge case:
// a label-only notification with zero new messages must still advance the cursor).
const historyResp = $input.first().json;
const account = $('Read account cursor').item.json;

const historyRecords = Array.isArray(historyResp.history) ? historyResp.history : [];
const idsSet = new Set();
for (const record of historyRecords) {
  for (const added of record.messagesAdded || []) {
    if (added.message && added.message.id) {
      idsSet.add(added.message.id);
    }
  }
}

// history.list's own top-level historyId is the new cursor. If the call itself
// failed (no historyId present), fall back to leaving the cursor unchanged rather
// than advancing it to something undefined.
const newCursor = historyResp.historyId || account.sync_cursor;

return [{
  json: {
    account_id: account.id,
    message_ids: Array.from(idsSet),
    new_cursor: newCursor,
  },
}];

// Splits the single upstream item's message_ids array into one item per id,
// so the loop below can fetch + normalize each message individually.
const data = $input.first().json;
return (data.message_ids || []).map((id) => ({ json: { message_id: id } }));
